// Procesar datos de viaje del usuario
const travelData = $input.first().json;

// Validar datos requeridos
const requiredFields = ['origin', 'destination', 'departure_date', 'return_date', 'travelers'];
const missingFields = requiredFields.filter(field => !travelData[field]);

if (missingFields.length > 0) {
  throw new Error(`Campos requeridos faltantes: ${missingFields.join(', ')}`);
}

// Calcular duración del viaje
const departure = new Date(travelData.departure_date);
const returnDate = new Date(travelData.return_date);
const tripDuration = Math.ceil((returnDate - departure) / (1000 * 60 * 60 * 24));

// Determinar temporada y precios esperados
const month = departure.getMonth();
let season = 'low';
let priceMultiplier = 1.0;

if ([5, 6, 7, 11, 12].includes(month)) { // Junio, Julio, Agosto, Noviembre, Diciembre
  season = 'high';
  priceMultiplier = 1.4;
} else if ([3, 4, 8, 9].includes(month)) { // Abril, Mayo, Septiembre, Octubre
  season = 'medium';
  priceMultiplier = 1.2;
}

// Generar ID único de búsqueda
const searchId = `travel_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

return [{
  // Datos originales del usuario
  ...travelData,

  // Métricas calculadas
  trip_duration: tripDuration,
  season: season,
  price_multiplier: priceMultiplier,

  // Metadata
  search_id: searchId,
  processed_at: new Date().toISOString(),
  user_id: travelData.user_id || `user_${Math.random().toString(36).substr(2, 9)}`,

  // Configuración de APIs
  currency: travelData.currency || 'USD',
  locale: travelData.locale || 'en-US',

  // Rangos de fechas para búsqueda flexible
  flexible_dates: {
    departure_min: new Date(departure.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    departure_max: new Date(departure.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    return_min: new Date(returnDate.getTime() - 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    return_max: new Date(returnDate.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  }
}];

// Procesar resultados provenientes de HotelAPI (RapidAPI)
const hotelData = $node['HotelAPI'].json; // Nodo HTTP Request a hotelapi5.p.rapidapi.com
const userData = $node['Process Travel Data'].json;

// Extraer mejor opción de hotel
const bestHotel = hotelData?.data?.[0] || {}; // Ajusta según estructura real del JSON que devuelve la API

// Calcular costos y métricas
const hotelPrice = bestHotel.price || 0;
const marketAverage = hotelPrice * 1.25;
const savings = marketAverage - hotelPrice;
const savingsPercentage = ((savings / marketAverage) * 100).toFixed(1);

// Crear enlace de afiliado (si lo tienes configurado en RapidAPI o tu sitio)
const hotelAffiliateLink = `https://hotelapi5.p.rapidapi.com/search?ss=${encodeURIComponent(userData.destination)}&checkin=${userData.departure_date}&checkout=${userData.return_date}`;

// Construir itinerario básico
const itinerary = {
  day_by_day: generateItinerary(userData, bestHotel),
  total_cost: hotelPrice,
  cost_breakdown: {
    hotel: hotelPrice,
    food: 100,
    activities: 50
  }
};

// Alertas de precio
const priceAlerts = [];

if (savingsPercentage > 10) {
  priceAlerts.push({
    type: 'great_deal',
    message: `¡Excelente precio! Ahorro estimado de ${savingsPercentage}%`,
    priority: 'high'
  });
}

if (userData.budget && hotelPrice > userData.budget) {
  priceAlerts.push({
    type: 'over_budget',
    message: `El alojamiento supera tu presupuesto en $${hotelPrice - userData.budget}`,
    priority: 'medium'
  });
}

// Resultado final para enviar al Webhook Response
return [{
  ...userData,

  best_hotel: {
    hotel_name: bestHotel.name || 'Hotel recomendado',
    price: hotelPrice,
    rating: bestHotel.rating || 0,
    review_count: bestHotel.reviews || 0,
    distance: bestHotel.distance || 'N/A',
    affiliate_link: hotelAffiliateLink
  },

  // Sin vuelos ni alternativas
  total_cost: hotelPrice,
  market_average: marketAverage,
  total_savings: savings,
  savings_percentage: savingsPercentage,

  itinerary: itinerary,
  price_alerts: priceAlerts,

  ai_recommendations: [
    "Elige opciones con cancelación gratuita.",
    "Revisa hoteles con desayuno incluido.",
    "Considera ubicaciones cercanas al centro turístico."
  ],
  confidence_score: 0.9,

  search_completed_at: new Date().toISOString(),
  price_valid_until: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
}];

// Función auxiliar para itinerario
function generateItinerary(userData, hotel) {
  const duration = userData.trip_duration || 3;
  const itinerary = [];

  for (let i = 0; i < duration; i++) {
    const day = {
      day: i + 1,
      date: new Date(new Date(userData.departure_date).getTime() + i * 86400000)
        .toISOString()
        .split('T')[0],
      activities: []
    };

    if (i === 0) {
      day.activities = ['Llegada al destino', 'Check-in en el hotel', 'Exploración local', 'Cena de bienvenida'];
    } else if (i === duration - 1) {
      day.activities = ['Desayuno de despedida', 'Check-out del hotel', 'Últimas compras', 'Regreso'];
    } else {
      day.activities = ['Desayuno en el hotel', 'Excursión local', 'Tiempo libre', 'Cena típica'];
    }

    itinerary.push(day);
  }

  return itinerary;
}

